import { Mesh, PlaneGeometry, Group, Color, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uniform, uv, vec2, mix, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const Group = THREE.Group;
  const Mesh = THREE.Mesh;
  const PlaneGeometry = THREE.PlaneGeometry;
  const Color = THREE.Color;
  const Vector2 = THREE.Vector2;

  const group = new Group();
  group.name = 'hub-journal-quote-panel';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  // Plane dimensions match atlas rect 512x320 -> 1.6:1
  const planeW = 2.5;
  const planeH = planeW * (320 / 512);

  // --- Textured face plane (image content / quote rendered in texture) ---
  const planeGeo = new PlaneGeometry(planeW, planeH, 1, 1);
  const faceMat = new MeshBasicNodeMaterial({ transparent: true });
  faceMat.toneMapped = true;

  const faceMesh = new Mesh(planeGeo, faceMat);
  faceMesh.position.set(0, 0, 0);
  group.add(faceMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    faceMat.map = tex;
    faceMat.needsUpdate = true;
  });

  // --- Backing board: subtle dark card behind the texture for depth + edge ---
  const boardGeo = new PlaneGeometry(planeW + 0.12, planeH + 0.12, 1, 1);
  const boardMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.7,
    metalness: 0.3,
    transparent: true,
    opacity: 0.95,
  });
  const boardMesh = new Mesh(boardGeo, boardMat);
  boardMesh.position.set(0, 0, -0.02);
  group.add(boardMesh);

  // --- Accent edge bar: thin signal-red strip on the left edge ---
  const edgeGeo = new PlaneGeometry(0.06, planeH + 0.12, 1, 1);
  const edgeMat = new MeshBasicNodeMaterial({ color: accent });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(-(planeW * 0.5 + 0.06), 0, 0.005);
  group.add(edgeMesh);

  // --- Subtle contact shadow below panel ---
  const shadowGeo = new PlaneGeometry(planeW * 1.15, 0.45, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({
    color: ink,
    transparent: true,
    opacity: 0.45,
    depthWrite: false,
  });
  // radial-ish falloff via node: fade alpha at edges
  const suv = uv();
  const sx = suv.x.mul(2).sub(float(1));
  const sy = suv.y.mul(2).sub(float(1));
  const sr = sx.mul(sx).add(sy.mul(sy)).sqrt();
  shadowMat.transparent = true;
  shadowMat.opacity = float(1).sub(smoothstep(float(0.3), float(1.0), sr)).mul(0.5);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -(planeH * 0.5 + 0.12), -0.03);
  shadowMesh.rotation.x = -0.1;
  group.add(shadowMesh);

  // --- Hint glow behind panel (gives the dark stage a lit pocket) ---
  const glowGeo = new PlaneGeometry(planeW * 1.6, planeH * 1.6, 1, 1);
  const glowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const guv = uv();
  const gx = guv.x.mul(2).sub(float(1));
  const gy = guv.y.mul(2).sub(float(1));
  const gr = gx.mul(gx).add(gy.mul(gy)).sqrt();
  const glowColor = mix(new Color('#1a1015'), surface, smoothstep(float(0), float(0.8), gr));
  glowMat.colorNode = glowColor;
  glowMat.opacityNode = float(1).sub(smoothstep(float(0.2), float(1.0), gr)).mul(0.6);
  const glowMesh = new Mesh(glowGeo, glowMat);
  glowMesh.position.set(0, 0, -0.08);
  group.add(glowMesh);

  // --- Rim light for the board (so metalness reads) ---
  const rimLight = new THREE.DirectionalLight(accent, 0.55);
  rimLight.position.set(-2.5, 1.2, 1.5);
  group.add(rimLight);

  // --- Apply cinematic primitive: parallax-scroll ---
  const primitiveResults = [];
  const primList = config.cinematicPrimitives ?? [];
  for (const prim of primList) {
    if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
      const res = ctx.primitives[prim.name](group, prim.params ?? {});
      primitiveResults.push(res);
    }
  }

  // --- Interaction handlers ---
  const timeline = gsap.timeline();

  const pressDown = () => {
    gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  };
  const pressUp = () => {
    gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' });
  };

  group.userData.handlers = {
    pointerover: () => {
      gsap.to(group.position, {
        y: (config.scenePosition?.[1] ?? 0) + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      gsap.to(edgeMesh.scale, { y: 1.15, duration: 0.4, ease: 'power2.out' });
    },
    pointerout: () => {
      gsap.to(group.position, {
        y: config.scenePosition?.[1] ?? 0,
        duration: 0.6,
        ease: 'power3.out',
      });
      gsap.to(edgeMesh.scale, { y: 1, duration: 0.4, ease: 'power2.out' });
    },
    pointerdown: () => {
      pressDown();
    },
    pointerup: () => {
      pressUp();
      ctx.emit('hub-journal.select', { source: 'hub-journal-quote-panel' });
    },
  };

  // --- Entrance animation ---
  group.position.set(
    config.scenePosition?.[0] ?? 0,
    (config.scenePosition?.[1] ?? 0) + 0.4,
    config.scenePosition?.[2] ?? 0
  );
  group.scale.set(1, 1, 1);
  group.userData.handlers._entrance = timeline
    .to(group.position, {
      y: config.scenePosition?.[1] ?? 0,
      duration: 0.7,
      ease: 'power3.out',
    })
    .to(group.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.45,
      ease: 'power2.out',
    }, '-=0.35')
    .to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    timeline.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMesh.scale);
    for (const res of primitiveResults) {
      if (res && typeof res.cleanup === 'function') res.cleanup();
    }
    planeGeo.dispose();
    faceMat.dispose();
    boardGeo.dispose();
    boardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    glowGeo.dispose();
    glowMat.dispose();
  };

  return group;
}
